        for(const auto& source:fact.source_armies){const auto* army=find(s.armies,source.id);const auto* original=formation(s,source.id);const auto* campaign=find(s.campaigns,source.campaign_id);if(!army||!original||army->status!="closed"||source.id==receiver->id||!closed.insert(source.id).second||source.formation_source_id!=army->formation_source||source.organization_id!=army->organization_id||source.campaign_id!=army->order_id||source.inventory_id!=army->inventory_id||source.wallet_id!=army->wallet_id||!same_values(source.unit_ids,units[source.id])||!same_values(source.member_actor_ids,people[source.id])||!source.retainers.empty()||!campaign||campaign->settlement_id!=fact.id||campaign->status!="closed"||!campaign->objective_result||campaign->objective_result->kind!="integrated"||campaign->objective_result->source_id!=std::optional<StableId>(fact.id))return common_failure("MilitaryIntegrationSourceMismatch",source.id);campaigns.insert(source.campaign_id);for(const auto& unit:source.units){if(!has(source.unit_ids,unit.id)||unit.organization_id!=source.organization_id||unit.army_id!=source.id||!unit.retainer_sources.empty())return common_failure("MilitaryIntegrationUnitSourceMismatch",unit.id);auto sorted=unit.fit;for(const auto* group:{&unit.wounded,&unit.dead,&unit.captured,&unit.deserted})sorted.insert(sorted.end(),group->begin(),group->end());auto roster=unit.member_ids;std::sort(sorted.begin(),sorted.end());std::sort(roster.begin(),roster.end());if(!unique(roster)||sorted!=roster)return common_failure("MilitaryIntegrationRosterMismatch",unit.id);}if(source.units.size()!=source.unit_ids.size())return common_failure("MilitaryIntegrationRosterMismatch",source.id);expected_units.insert(expected_units.end(),source.unit_ids.begin(),source.unit_ids.end());expected_people.insert(expected_people.end(),source.member_actor_ids.begin(),source.member_actor_ids.end());units[source.id].clear();people[source.id].clear();}
